// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(c));
        vm.assume(actor != address(0));
        vm.assume(amount > 0);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();

        uint256 balanceBefore = c.getBalance(actor);
        uint256 contractEthBefore = address(c).balance;

        vm.prank(actor);
        c.withdrawBalance();

        uint256 balanceAfter = c.getBalance(actor);
        uint256 contractEthAfter = address(c).balance;

        assertTrue(balanceAfter == 0 && contractEthBefore - contractEthAfter == balanceBefore);
    }
}
